import { h, render, Component, options } from 'preact';

import constants from './../constants';

class UpdateForm extends Component {

  constructor(props) {
    super(props);

    this.state = {
      gps_devices_: []
    };
  }

  componentDidMount() {
    let o = this.props.item;
    if (!o) {
      let msg = 'No se encontró la información del vehiculo';
      alert(msg);
      return;
    }

    let inputAlias = document.querySelector('#input-u-alias');
    let inputLicensePlates = document.querySelector('#input-u-license-plates');
    let inputDescription = document.querySelector('#input-u-description');
    let inputResponsible = document.querySelector('#input-u-responsible');
    let inputNote = document.querySelector('#input-u-note');
    let inputStatus = document.querySelector('#input-u-status');

    inputAlias.value = o.alias;
    inputLicensePlates.value = o.license_plates;
    inputDescription.value = o.description;
    inputResponsible.value = o.responsible;
    inputNote.value = o.note;
    inputStatus.checked = o.status;

    this.getGPSDevices();
  }

  getGPSDevices() {
    let self = this;

    let url = `${constants.URL_SERVER_GPS_DEVICES}/list`;

    let xhr = $.ajax({
      url: url,
      type: constants.METHOD_GET,
      dataType: constants.JSON,
    });

    xhr.done((res, status, response) => {
      if (response.status == constants.STATUS_OK) {
        self.setState({ gps_devices_: res.docs }, () => {

          let o = this.props.item;
          if(o) {
            let inputGPSDevice = document.querySelector('#input-u-gps-device');
            if (o.gps_device_id) inputGPSDevice.value = o.gps_device_id;
          }
        });

      } else if (response.status == constants.STATUS_ACCEPTED) {
        alert(res.message);
      }
    });

    xhr.fail((res, status, respose) => {
      if (res.responseJSON) {
        let json = res.responseJSON;
        alert(json.message);
      } else {
        alert(constants.MESSAGE_ERROR);
      }
    });
  }

  handleUpdate() {
    let self = this;

    let fn = (evt) => {
      evt.preventDefault();

      let o = this.props.item;
      if (!o) {
        let msg = 'No se encontró la información del vehicle';
        alert(msg);
        return;
      }      

      let inputGPSDevice = document.querySelector('#input-u-gps-device');
      let inputAlias = document.querySelector('#input-u-alias');
      let inputLicensePlates = document.querySelector('#input-u-license-plates');
      let inputDescription = document.querySelector('#input-u-description');
      let inputResponsible = document.querySelector('#input-u-responsible');
      let inputNote = document.querySelector('#input-u-note');
      let inputStatus = document.querySelector('#input-u-status');

      let gps_device = inputGPSDevice.value.trim();
      let alias = inputAlias.value.trim();
      let license_plates = inputLicensePlates.value.trim();
      let description = inputDescription.value.trim();
      let responsible = inputResponsible.value.trim();
      let note = inputNote.value.trim();
      let status = inputStatus.checked;

      let json = {};

      if (gps_device != '') {
        let vInt = parseInt(gps_device);
        if (vInt) {
          json.gps_device_id = vInt;
        }
      }

      json.alias = alias;
      json.license_plates = license_plates;
      json.description = description;
      json.responsible = responsible;
      json.note = note;
      json.status = status;

      self.props.onUpdate(json, o.id);
    };

    return fn;
  }

  handleBack() {
    let self = this;

    let fn = () => {
      self.props.onBack();
    };

    return fn;
  }

  createOpt() {
    let self = this;

    let fn = (item, index) => {
      return <option key={index} value={item.id}>{item.imei}</option>;
    };

    return fn;
  }

  render(props, state) {
    return (
      <section>
        <div className="row">
          <div className="col-md-12">
            <h3>Editar Vehiculo</h3>

            <form onSubmit={this.handleUpdate()} >

              <div className="form-group">
                <label htmlFor="input-u-gps-device">Dispositivo GPS</label>
                <select id="input-u-gps-device" className="form-control">
                  <option selectev>Dispositivo GPS</option>
                  {state.gps_devices_.map(this.createOpt())}
                  <option value="-1">Ninguno</option>
                </select>
              </div>

              <div className="form-group">
                <label htmlFor="input-u-alias">Alias</label>
                <input type="text" className="form-control" id="input-u-alias" placeholder="Alias" />
              </div>

              <div className="form-group">
                <label htmlFor="input-u-license-plates">Placas</label>
                <input type="text" className="form-control" id="input-u-license-plates" placeholder="Placas" />
              </div>

              <div className="form-group">
                <label htmlFor="input-u-description">Descripción</label>
                <input type="text" className="form-control" id="input-u-description" placeholder="Descripción" />
              </div>

              <div className="form-group">
                <label htmlFor="input-u-responsible">Responsable</label>
                <input type="text" className="form-control" id="input-u-responsible" placeholder="Responsable" />
              </div>

              <div className="form-group">
                <label htmlFor="input-u-note">Nota</label>
                <input type="text" className="form-control" id="input-u-note" placeholder="Nota" />
              </div>

              <div className="form-check">
                <input type="checkbox" class="form-check-input" id="input-u-status" />
                <label class="form-check-label" htmlFor="input-u-status">Activo</label>
              </div>

              <div className="form-group col-md-12">
                <br />
                <br />
                <button type="button" className="btn btn-warning" onClick={this.handleBack()}>Cancelar</button>
                <button type="submit" className="btn btn-primary">Guardar</button>
              </div>

            </form>
          </div>
        </div>
      </section>
    );
  }
}

export default UpdateForm;